<style>
   :root{--vn-red:#b41420;--vn-red-deep:#6d0c13;--vn-red-soft:rgba(180, 20, 32, 0.12);--vn-gold:#ffd447;--vn-gold-deep:#c99714;--vn-white:#fffaf0}.home-page{position:relative;isolation:isolate}.home-page::before{content:'';position:absolute;inset:0 10px auto;height:360px;z-index:-1;pointer-events:none;background:radial-gradient(circle at 10% 10%,rgb(255 212 71 / .12),transparent 24%),radial-gradient(circle at 92% 16%,rgb(180 20 32 / .15),transparent 28%),linear-gradient(180deg,rgb(180 20 32 / .045),transparent 78%)}.tet-29-hero{position:relative;min-height:270px;margin:28px 0 14px;padding:34px 36px;overflow:hidden;border:1px solid rgb(180 20 32 / .34);border-radius:24px;background:linear-gradient(118deg,rgb(83 7 14 / .98) 0%,rgb(155 16 28 / .97) 50%,rgb(103 9 18 / .98) 100%);box-shadow:0 18px 50px rgb(83 7 14 / .18);color:#fff}.tet-29-hero::before,.tet-29-hero::after{content:'';position:absolute;pointer-events:none;border-radius:50%}.tet-29-hero::before{width:340px;height:340px;right:-130px;top:-150px;border:1px solid rgb(255 212 71 / .28);box-shadow:0 0 0 34px rgb(255 212 71 / .035),0 0 0 74px rgb(255 212 71 / .025)}.tet-29-hero::after{width:230px;height:230px;left:-130px;bottom:-165px;border:1px solid rgb(255 255 255 / .13)}.tet-29-copy{position:relative;z-index:3;max-width:720px}.tet-29-kicker{display:inline-flex;align-items:center;gap:8px;padding:7px 11px;margin-bottom:16px;border:1px solid rgb(255 212 71 / .4);border-radius:999px;background:rgb(255 255 255 / .06);color:#ffe69a;font:700 0.62rem/1 var(--mono);letter-spacing:.17em}.tet-29-title{margin:0;font-family:'Cinzel',serif;font-size:clamp(2rem, 4vw, 4rem);line-height:1.02;letter-spacing:.045em;color:#fff;text-shadow:0 5px 28px rgb(0 0 0 / .25)}.tet-29-title span{display:block;color:#fff}.tet-29-title strong{display:block;color:var(--vn-gold);font-size:.72em;letter-spacing:.14em;margin-top:6px}.tet-29-motto{margin:16px 0 7px;font:800 .76rem/1.4 var(--mono);letter-spacing:.23em;color:#fff3c4}.tet-29-note{marg