rgb(180 20 32 / .18);box-shadow:inset 0 0 0 26px rgb(180 20 32 / .025)}.tet-29-countdown::after{right:-75px;bottom:-110px;border:1px solid rgb(255 190 0 / .22);box-shadow:inset 0 0 0 26px rgb(255 190 0 / .025)}.tet-29-countdown-head{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:18px}.tet-29-countdown-kicker{display:block;margin-bottom:5px;color:#9d151e;font:800 .58rem/1.2 var(--mono);letter-spacing:.22em}.tet-29-countdown-title{margin:0;color:#3a2023;font:800 clamp(1rem, 1.8vw, 1.25rem)/1.2 'Cinzel',serif;letter-spacing:.05em}.tet-29-countdown-title span{color:#b41420}.tet-29-countdown-live{display:inline-flex;align-items:center;gap:8px;padding:7px 11px;border:1px solid rgb(180 20 32 / .18);border-radius:999px;background:rgb(180 20 32 / .055);color:#9d151e;font:800 .55rem/1 var(--mono);letter-spacing:.12em;white-space:nowrap}.tet-29-countdown-live span{width:7px;height:7px;border-radius:50%;background:#b41420;box-shadow:0 0 0 5px rgb(180 20 32 / .08);animation:tet-29-countdown-pulse 1.4s ease-in-out infinite}.tet-29-countdown-grid{position:relative;z-index:1;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.tet-29-time-card{position:relative;min-height:100px;padding:18px 14px 14px;border:1px solid rgb(180 20 32 / .14);border-radius:14px;background:rgb(255 255 255 / .58);text-align:center;box-shadow:inset 0 -2px 0 rgb(180 20 32 / .05);transition:transform .25s ease,border-color .25s ease,box-shadow .25s ease}.tet-29-time-card::after{content:'';position:absolute;left:20%;right:20%;bottom:8px;height:2px;border-radius:99px;background:linear-gradient(90deg,transparent,#b41420,#f0bf27,transparent);opacity:.55}.tet-29-time-card:hover{transform:translateY(-3px);border-color:rgb(180 20 32 / .30);box-shadow:0 10px 22px rgb(103 9 18 / .07)}.tet-29-time-card strong{display:block;color:#8f121a;font:800 clamp(2rem, 4vw, 3rem)/.95 'JetBrains Mono',monospace;letter-spacing:-.06em;text-shadow:0 4px